      role1 = 384000,
      role2 = 301101,
      role3 = 301209,
      roleanim = 1.1,
      sentence = "Didn't exactly go back on your word? At the party, you kept staring at me. Then you were so drunk, I had to carry you. And when I was on stage giving my speech...",
