      music = "60_Beaytiful_Daily",
      renwu = "npc",
      role1 = 384000,
      role2 = 301106,
      role3 = 301201,
      roleanim = 1.2,
      sentence = "Without waiting for me to finish, I was wrapped up in a forceful embrace that also seemed pent-up for a long time.",
