      renming = "Kiro",
      renwu = "npc",
      role1 = 384000,
      role2 = 301101,
      role3 = 301201,
      roleanim = 1.2,
      sentence = "And although Mr. Kim gave a thumbs up, when I'm studying this character, I still think there's some distance between him and me.",
      voice = 2,
      next = {40}
    },
    [40] = {
      beijing = 4755,
      dialog = 3,
