      renwu = "npc",
      role1 = 384000,
      role2 = 301102,
      role3 = 301201,
      roleanim = 1.2,
      sentence = "He relaxed his shoulders and lazily rested his chin on my shoulder. His voice, sounding deeper than normal, flowed on next to my ear.",
      next = {41}
    },
    [41] = {
      beijing = 4755,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "60_Beaytiful_Daily",
      renming = "Kiro",
      renwu = "npc",
      role1 = 384000,
      role2 = 301106,
