      renwu = "npc",
      role1 = 384000,
      role2 = 301106,
      role3 = 301201,
      roleanim = 1.2,
      sentence = "He tilted his head and gently caressed my face with his fingertip, his eyes flowing with loving tenderness.",
      next = {45}
    },
    [45] = {
      beijing = 4755,
      dialog = 3,
      music = "60_Beaytiful_Daily",
      renwu = "npc",
      role1 = 384000,
      role2 = 301106,
      role3 = 301201,
      roleanim = 1.2,
      sentence = "I found myself breathing softer out of fear that I would ruin this emotional moment.",
      next = {46}
    },
    [46] = {
      beijing = 4755,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "60_Beaytiful_Daily",
      renming = "Kiro",
      renwu = "npc",
      role1 = 384000,
      role2 = 301106,
      role3 = 301201,
      roleanim = 1.2,
      sentence = "It's because I met someone very important. She keeps me from feeling lonely, and has taught me what that pang of missing someone feels like, and helped me find a place to call home.",
      voice = 2,
      next = {47}
    },
    [47] = {
