      dialog = 3,
      music = "60_Beaytiful_Daily",
      renwu = "npc",
      role1 = 384000,
      role2 = 301106,
      role3 = 301201,
      roleanim = 1.2,
      sentence = "He picked up my hand and placed it gently on his chest. The hot, vigorous heartbeat under my hand passed through my palm and became one with my veins.",
      next = {48}
    },
    [48] = {
      beijing = 4755,
