      idx = 3,
      male = 3,
      music = "60_Beaytiful_Daily",
      renming = "Kiro",
      renwu = "npc",
      role1 = 384000,
      role2 = 301106,
      role3 = 301201,
      roleanim = 1.2,
      sentence = "She has given me an irreplaceable warmth and has made me forget what it's like to be completely untethered from the world.",
      voice = 2,
