      idx = 3,
      male = 3,
      music = "60_Beaytiful_Daily",
      renming = "Kiro",
      renwu = "npc",
      role1 = 384000,
      role2 = 301106,
      role3 = 301201,
      roleanim = 1.2,
      sentence = "All I can do is try my best to imagine that \"Kiro\" is completely dissociated from my body until I can feel no love.",
