      dialog = 3,
      music = "60_Beaytiful_Daily",
      renwu = "npc",
      role1 = 384000,
      role2 = 301106,
      role3 = 301201,
      roleanim = 1.2,
      sentence = "His tone was matter-of-fact, but I couldn't even imagine how hard it must be to strip himself bare like this.",
      next = {52}
    },
    [52] = {
      beijing = 4755,
      dialog = 3,
      music = "60_Beaytiful_Daily",
      renwu = "npc",
      role1 = 384000,
      role2 = 301106,
      role3 = 301201,
      roleanim = 1.2,
      sentence = "An image of him popped into my mind, cooped up in his room wrestling with his emotions in his dogged pursuit of perfection.",
      next = {53}
    },
    [53] = {
      beijing = 4755,
      dialog = 3,
      music = "60_Beaytiful_Daily",
      renwu = "npc",
      role1 = 384000,
      role2 = 301106,
      role3 = 301201,
      roleanim = 1.2,
      sentence = "With a stinging heart, I reached out and stroked his brow. I saw him seamlessly push down the weariness that I knew must be there. He took my hand and held it at the corner of his mouth.",
      next = {54}
    },
    [54] = {
      beijing = 4755,
      dialog = 2,
      idx = 3,
      male = 3,
      music = "60_Beaytiful_Daily",
      renming = "Kiro",
      renwu = "npc",
      role1 = 384000,
      role2 = 301101,
      role3 = 301201,
      roleanim = 1.2,
      sentence = "So you don't need to worry. I'll do great tomorrow.",
