      next = {55}
    },
    [55] = {
      beijing = 4755,
      dialog = 3,
      music = "60_Beaytiful_Daily",
      renwu = "npc",
      role1 = 384000,
      role2 = 301101,
      role3 = 301201,
      roleanim = 1.2,
      sentence = "His confident voice was like a consolation, and also like a veiled request. I put aside all my worries and held him again, but there was still a question lingering in my mind—",
      next = {56}
    },
    [56] = {
      beijing = 4755,
