      renwu = "npc",
      role1 = 384000,
      role2 = 301107,
      role3 = 301201,
      roleanim = 1.2,
      sentence = "But from the moment you entered my line of sight, I knew it was a lost cause.",
      voice = 2,
      next = {60}
    },
