      renming = "Kiro",
      renwu = "npc",
      role1 = 384000,
      role2 = 301106,
      role3 = 301201,
      roleanim = 1.2,
      sentence = "My body kept telling me that person was my most beloved. It wanted to go to you and hug you, beyond my control.",
      voice = 2,
