    },
    [76] = {
      beijing = 4755,
      dialog = 3,
      music = "Story_101_Courtshipdisplay",
      renwu = "npc",
      sentence = "With his \"prey\" in the net, he laughed softly. A kiss fell on the nape of my neck, and his sultry breath made me shiver.",
