    },
    [78] = {
      beijing = 4755,
      dialog = 3,
      music = "Story_101_Courtshipdisplay",
      renwu = "npc",
      sentence = "His gentle teasing made the fire in my heart blaze up. I tore away the headphones hanging around his neck and planted a heavy kiss there.",
